NavigationScreen::NavigationScreen(TFT_eSprite &_tft, bool &_deviceConnected, StateMachine &_stateManager, BLEService **_pService,
                                   TFT_Display &_display,
                                   unsigned long &_currentMillis,
                                   bool &_receivingSec,
                                   bool &_receivingMap,
                                   int &_secBinaryLen,
                                   int &_mapBinaryLen,
                                   unsigned long &_lastDrawTime)
    : tft(&_tft), deviceConnected(&_deviceConnected), stateManager(&_stateManager), pService(_pService), display(&_display),
      currentMillis(&_currentMillis),
      receivingSec(&_receivingSec),
      receivingMap(&_receivingMap),
      secBinaryLen(&_secBinaryLen),
      mapBinaryLen(&_mapBinaryLen),
      lastDrawTime(&_lastDrawTime)
{
  name = "NavigationScreen";
}

class State;

void NavigationScreen::enter()
{
  handleDeviceUpdate();
}

void NavigationScreen::loop()
{
  if ((!*receivingSec && *secBinaryLen >= 5) || (!*receivingMap && *mapBinaryLen >= 5) && *deviceConnected)
  {
    startNavigation();
  }
  else if (prevConnected != *deviceConnected)
  {
    handleDeviceUpdate();
    prevConnected = *deviceConnected;
  }
}

void NavigationScreen::exit()
{
}

void NavigationScreen::btnPress(String button)
{
  Serial.println("NavigationScreen: btnPress: " + button);
  if (button == "LEFT")
  {
    stateManager->changeState("ConfigScreen");
  }
}

void NavigationScreen::handleDeviceUpdate()
{
  Serial.println("NavigationScreen: Device connection status changed: " + String(*deviceConnected ? "Connected" : "Disconnected"));
  tft->createSprite(240, 240);
  tft->fillSprite(TFT_BLACK);
  tft->setFreeFont(&FreeSans12pt7b);
  tft->setTextColor(TFT_WHITE);
  if (*deviceConnected)
  {
    tft->drawString("Start navigation", 43, 102);
    tft->drawString("on the device", 56, 127);
  }
  else
  {
    tft->drawString("No device", 68, 102);
    tft->drawString("Connected", 63, 127);
  }
  tft->fillEllipse(17, 120, 15, 15, 0xFFFF);
  tft->pushImage(7, 110, 20, 20, arrow_left_invert);
  tft->pushSprite(0, 0);
}

